// The day's affirmation in Slovenian, for the country pages in Slovenian. Written by scripts/home_extras.py from data/affirmations-i18n/; do not edit.
(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"Ni ti treba danes narediti vsega. Dovolj je naslednja majhna stvar.\", \"Utrujenost ni isto kot neuspeh. Utrujena si, ker si vsak dan znova tu zanje.\", \"Posoda lahko počaka. Smeš se usesti za pet minut.\", \"Tudi kosmiči za večerjo pomenijo, da si nahranila družino.\", \"Počitka si ni treba zaslužiti. Smeš počivati že zdaj.\", \"Včasih je zmaga že to, da so vsi zdržali do spanja. To je prava zmaga.\", \"Narediš več, kot kdorkoli vidi. Jaz to vidim.\", \"Razmetana hiša in ljubljeni otroci. To je dobra kupčija.\", \"Na težek dan je tvoje najboljše videti drugače, pa vseeno šteje.\", \"En globok vdih. Spusti ramena. Dobro ti gre.\", \"Danes je v redu spustiti letvico. Kak drug dan jo lahko spet dvigneš.\", \"Prositi za pomoč je znak moči, ne šibkosti.\", \"Smeš reči ne še eni obveznosti.\", \"Če si se danes počutila osamljeno, nisi edina mama, ki se je tako počutila. Veliko nas je.\", \"Zaslužiš prijateljico, ki te vpraša, kako si, in počaka na odgovor.\", \"V redu je, da se oglasiš prva. Večina mam upa, da se bo kdo oglasil.\", \"Če se počutiš nevidno, to ne pomeni, da nisi pomembna. Zelo si pomembna.\", \"Tvoja čustva so razumljiva. Nisi „preveč“.\", \"Tukaj ti ni treba razlagati svojega težkega dne. Razumemo.\", \"Sporočilo drugi mami z besedama „tudi jaz“ lahko obrne cel dan.\", \"Hranjenje, previjanje, zibanje in spet od začetka. To je pravo delo, tudi ko je videti kot sedenje pri miru.\", \"Ti in tvoj dojenček se še spoznavata. Nikamor se ne mudi.\", \"Dnevi z novorojenčkom so dolgi. To obdobje ne bo trajalo večno.\", \"Če si danes le poskrbela, da je bil majhen človek sit in na toplem, si opravila veliko delo.\", \"Ni ti treba takoj nazaj v staro formo. Lahko si preprosto tam, kjer si.\", \"Kakor koli hraniš dojenčka, skrbiš zanj. To je tisto, kar šteje.\", \"Lahko si hkrati neprespana in polna ljubezni.\", \"Drži dojenčka in pozabi na hišo. Hiša bo še vedno tu.\", \"Izbruh trme v trgovini te ne naredi slabe mame. Pomeni le, da imaš malčka.\", \"Malčki preizkušajo meje, ker se ob tebi počutijo varne.\", \"Danes si ostala mirna minuto dlje kot včeraj. To šteje.\", \"Če si izgubila živce, objem in „oprosti“ popravita veliko. In jih naučita nekaj dobrega.\", \"Lepljive ročice, glasni glasovi, velika čustva. Vzgajaš celega človeka.\", \"Peti „zakaj?“ v isti uri je majhna glavica, ki raste.\", \"Za srečen spomin ne potrebuješ popolnega dne.\", \"Zaloputnjena vrata niso konec zgodbe. Pusti luč prižgano.\", \"Tvoj najstnik tega morda ne pove, a tvoja zanesljiva prisotnost je pomembna.\", \"Biti tista mirna v hiši je težko delo. In ti ga opravljaš.\", \"Nekateri najboljši pogovori se zgodijo v avtu. Kar vozi naprej.\", \"Odmikajo se, da bi odrasli, ne da bi te pustili za sabo.\", \"Ni ti treba poznati vseh odgovorov. Poslušanje je velik del tega.\", \"Veliki otroci te še vedno potrebujejo, le na tišji način.\", \"Za to, da vse zmoreš sama, je potrebna moč, ki je večina ljudi nikoli ne vidi.\", \"Za svojega otroka si dovolj dobra mama. Vedno si bila.\", \"En par rok, sto opravil. Bodi prizanesljiva do sebe.\", \"Tvoji otroci se ob tebi učijo, kako je videti močna in ljubeča oseba.\", \"Odmor ni zapuščanje svojega mesta. Tako zdržiš naprej.\", \"Nihče ne šteje točk. Pomembni sta ljubezen in to, da si tu.\", \"Žalost in ljubezen izvirata iz istega kraja. Pogrešanje pokaže, kako zelo si imela nekoga rada.\", \"Za žalovanje ni pravega roka. Vzemi si toliko časa, kot ga potrebuješ.\", \"Na težke obletnice bodi do sebe tako nežna, kot bi bila do prijateljice.\", \"Lahko nosiš žalost in se vseeno smeješ s svojimi otroki. Oboje je resnično.\", \"Če si izgubila nosečnost ali otročka, je ta izguba resnična, prav tako kot tvoja ljubezen.\", \"Nekatere dni je žalost tiha, druge dni glasna. Oboje je v redu.\", \"Če ti primanjkuje denarja, ti zato ne primanjkuje ljubezni.\", \"Tvoji otroci si bodo bolj zapomnili čas s tabo kot stvari, ki si jih kupila.\", \"Vprašati za pomoč pri računih je pametno, ne sramotno. Prav za to ta pomoč obstaja.\", \"Brezplačno popoldne v parku je lahko najlepši dan v tednu.\", \"Denar si raztegnila še za en teden. Za to je potrebna prava spretnost.\", \"Skrb zaradi denarja izčrpava. Nosiš veliko, pa si še vedno tu.\", \"Danes si spila kozarec vode. Začni pri tem.\", \"Vsi so prišli skozi vrata. Mogoče čevlji niso bili v paru. Še vedno zmaga.\", \"Opravila si tisti klic, ki te ga je bilo strah. To je bilo pogumno.\", \"Danes si se smejala. Obdrži to.\", \"Topel obrok, čista majica, pravljica za lahko noč. Iz majhnih stvari je sestavljeno otroštvo.\", \"Danes si bila prijazna do nekoga, četudi samo do sebe.\", \"Napredek, ne popolnost. Danes si naredila korak naprej.\", \"S seznama si odkljukala eno stvar. To je ena več kot nobena.\", \"Dobra mama si. To, da te skrbi, pokaže, kako zelo ti je mar.\", \"Vredna si več od tega, kar postoriš v enem dnevu.\", \"Tvoji otroci ne potrebujejo popolne mame. Potrebujejo tebe in tebe imajo.\", \"Bodi tako potrpežljiva do sebe, kot si do svojih otrok.\", \"Smeš zavzeti prostor, si kaj želeti in imeti svoje sanje.\", \"Napaka ne izbriše ljubezni. Jutri je nov začetek.\", \"Za nekoga si ves svet, pa si vseeno tudi svoja oseba.\", \"V redu je, če ne uživaš v vsaki minuti. Svoje otroke lahko še vedno ljubiš z vsem srcem.\", \"Ni enega samega pravega načina, kako biti mama. Tvoj način je v redu.\", \"Kot v položaju drevesa je v redu, če se zamajaš. Ravnotežje lahko spet najdeš.\", \"Stopala postavi trdno kot v položaju gore. Bolj stabilna si, kot se počutiš.\", \"Bojevnik II: močne noge, razprte roke. To si ti, pripravljena na ta teden.\", \"Vdihni na štiri, izdihni na štiri. Tukaj si in dobro ti gre.\", \"Razpri se kot zvezda. Smeš zavzeti prostor.\", \"Širok, nizek počep je težko zadržati. Dolg dan prav tako. In ti ga zdržiš.\", \"Lahko se nagneš kot polmesec in še vedno stojiš.\", \"Ni ti treba že seči do prstov na nogah. Vsak delček raztezanja šteje.\", \"Položaj trikotnika: ena roka dol, druga gor. Ostani prizemljena in segaj naprej.\", \"Pozno je. Kar danes ni bilo narejeno, lahko počaka do jutri.\", \"Ob tej uri pokonci z dojenčkom? Veliko mam je ravno zdaj budnih s tabo.\", \"Hiša je tiha. Ta trenutek je tvoj. Dihaj.\", \"Današnji dan si prebrodila. Več od tega danes ni bilo treba.\", \"Če ti misli nocoj ne dajo miru, jih zapiši in naj počakajo do jutra.\", \"Odpočij si oči. Jutri lahko začneš znova.\", \"Prazniki so lahko težki in hkrati veseli. Kakor koli se počutiš v tem času, je v redu.\", \"Ni nujno, da je miza popolna. Pomembni so ljudje okoli nje.\", \"Če ti letos kdo manjka za mizo, bodi nežna do svojega srca.\", \"Hvala, mama, za vsak obrok, vsako vožnjo in vsak objem.\", \"Ni ti treba gostiti, peči ali se ves čas smehljati. Preprost praznik je še vedno praznik.\", \"Najlepše darilo, ki ga letos dobijo tvoji otroci, je čas s tabo.\", \"Tudi majhen praznik je poln ljubezni. Za to, da je poseben, ni treba veliko denarja.\", \"Hladni dnevi, topli objemi. Ti si toplo mesto v svojem domu.\", \"V redu je izpustiti del prazničnega vrveža. Tudi mir je darilo.\", \"Če je ta čas letos težak, nisi sama. Dan za dnem.\"]";D.body.appendChild(e)})();
